const $=id=>document.getElementById(id), canvas=$('space'),ctx=canvas.getContext('2d');
const TAU=Math.PI*2, reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let data=null, planets=[],hits=[],selected=0,width=0,height=0,rotation=-.4,tilt=.56,zoom=1,playing=!reduced,dirty=true;
let pointer=null,dragged=false,last=0,visible=true,hovered=null;
const stars=Array.from({length:230},(_,i)=>({x:hash(i+80),y:hash(i+650),r:.35+hash(i+900)*.8,a:.08+hash(i+1200)*.4}));
function hash(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function orbital(count,peak){const t=Math.log1p(count)/Math.log1p(Math.max(peak,1));return {radius:.19+.74*(1-t),size:1.2+5*t,t}}
function validate(d){
 if(!d||d.schemaVersion!==1||!['commits','contributions'].includes(d.metric)||typeof d.demo!=='boolean'||typeof d.username!=='string'||!/^[a-z\d-]{1,39}$/i.test(d.username)||!Array.isArray(d.days)||!d.days.length||d.days.length>366)throw Error('Use data.json generated by the included Commit Cosmos script.');
 const seen=new Set();
 for(const day of d.days){if(!/^\d{4}-\d{2}-\d{2}$/.test(day.date)||!Number.isFinite(Date.parse(day.date))||new Date(day.date+'T00:00:00Z').toISOString().slice(0,10)!==day.date||!Number.isSafeInteger(day.count)||day.count<0||seen.has(day.date))throw Error('Data contains an invalid date, duplicate day or invalid count.');seen.add(day.date)}
 d.days.sort((a,b)=>a.date.localeCompare(b.date));return d;
}
function load(d){
 data=validate(d);const peak=Math.max(...data.days.map(d=>d.count)),total=data.days.reduce((s,d)=>s+d.count,0);
 planets=data.days.map((d,i)=>({...d,...orbital(d.count,peak),angle:i/data.days.length*TAU-.9,index:i}));
 selected=data.days.reduce((best,d,i)=>d.count>data.days[best].count?i:best,0);
 $('identity').textContent='@'+data.username+' / '+data.days.length+' days in orbit';
 $('sourceBadge').textContent=data.demo?'DEMO DATA':'GITHUB / '+data.metric.toUpperCase();
 $('total').textContent=total.toLocaleString();$('metricLabel').textContent=data.metric+' in this period';
 $('active').textContent=data.days.filter(d=>d.count>0).length;$('peak').textContent=peak;
 $('empty').hidden=total>0;$('dateRange').textContent=data.days[0].date+' — '+data.days.at(-1).date;
 $('dataNote').textContent=data.demo?'You’re exploring sample data. Run the included GitHub workflow, then import your data.json.':'Real GitHub '+data.metric+'. Import a refreshed data.json any time to update this view.';
 $('daySelect').replaceChildren(...data.days.map((d,i)=>{const o=document.createElement('option');o.value=i;o.textContent=d.date+' · '+d.count+' '+data.metric;return o}));
 $('error').hidden=true;inspect(selected);dirty=true;
}
function inspect(i){if(!data)return;selected=(i+planets.length)%planets.length;const p=planets[selected];$('daySelect').value=selected;$('selectedCount').textContent=p.count;$('selectedMetric').textContent=data.metric;$('selectedOrbit').textContent=p.count===0?'Quiet day · outer dust belt':p.t>.75?'High activity · inner orbit':p.t>.35?'Steady activity · middle orbit':'Light activity · outer orbit';dirty=true}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);dirty=true}
function project(x,z){const xr=x*Math.cos(rotation)-z*Math.sin(rotation),zr=x*Math.sin(rotation)+z*Math.cos(rotation);const yr=zr*Math.sin(tilt),depth=zr*Math.cos(tilt),perspective=1/(1+depth*.00045);return {x:width/2+xr*perspective,y:height*.49+yr*perspective,z:depth,k:perspective}}
function sphere(p,r,t,alpha=1){const palette=t>.85?['#fff9d1','#ebc370','#7e511e','#241b18']:t>.28?['#ddffff','#6fd8e3','#146a83','#091a28']:['#afcde0','#46778d','#193b53','#091522'];ctx.globalAlpha=alpha;const g=ctx.createRadialGradient(p.x-r*.35,p.y-r*.4,.05,p.x,p.y,r);g.addColorStop(0,palette[0]);g.addColorStop(.27,palette[1]);g.addColorStop(.65,palette[2]);g.addColorStop(1,palette[3]);ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,r,0,TAU);ctx.fill();ctx.globalAlpha=1}
function render(){
 ctx.clearRect(0,0,width,height);ctx.fillStyle='#080f18';ctx.fillRect(0,0,width,height);
 for(const s of stars){ctx.fillStyle=`rgba(164,215,237,${s.a})`;ctx.beginPath();ctx.arc(s.x*width,s.y*height,s.r,0,TAU);ctx.fill()}
 if(!data)return;
 const scale=Math.min(width*.46,height*.8)*zoom;
 ctx.lineWidth=.6;
 for(let r=.19;r<=1;r+=.085){ctx.strokeStyle='rgba(92,151,171,.19)';ctx.beginPath();for(let i=0;i<=140;i++){const a=i/140*TAU,p=project(Math.cos(a)*r*scale,Math.sin(a)*r*scale);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.stroke()}
 const sun=project(0,0),halo=ctx.createRadialGradient(sun.x,sun.y,0,sun.x,sun.y,scale*.3);halo.addColorStop(0,'rgba(255,178,63,.23)');halo.addColorStop(1,'rgba(255,178,63,0)');ctx.fillStyle=halo;ctx.fillRect(0,0,width,height);
 hits=planets.map(p=>({...project(Math.cos(p.angle)*p.radius*scale,Math.sin(p.angle)*p.radius*scale),planet:p}));
 const sorted=[...hits].sort((a,b)=>b.z-a.z);let sunDrawn=false;
 function drawSun(){const r=Math.max(11,scale*.052);const glow=ctx.createRadialGradient(sun.x,sun.y,0,sun.x,sun.y,r*2.6);glow.addColorStop(0,'rgba(255,216,125,.75)');glow.addColorStop(1,'rgba(255,166,37,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(sun.x,sun.y,r*2.6,0,TAU);ctx.fill();const g=ctx.createRadialGradient(sun.x-r*.3,sun.y-r*.3,0,sun.x,sun.y,r);g.addColorStop(0,'#fff7d5');g.addColorStop(.6,'#ffcf72');g.addColorStop(1,'#da8e33');ctx.fillStyle=g;ctx.beginPath();ctx.arc(sun.x,sun.y,r,0,TAU);ctx.fill();ctx.strokeStyle='#f8df9d';ctx.lineWidth=.6;ctx.stroke()}
 for(const h of sorted){if(!sunDrawn&&h.z<=0){drawSun();sunDrawn=true}const p=h.planet,r=Math.max(.7,p.size*h.k*Math.sqrt(zoom)*Math.max(.7,Math.min(1.4,width/800)));h.r=r;sphere(h,r,p.t,p.count?1:.4);if(p.index===selected){ctx.strokeStyle='#c5f6f5';ctx.lineWidth=.7;ctx.beginPath();ctx.arc(h.x,h.y,r+4,0,TAU);ctx.stroke()}}
 if(!sunDrawn)drawSun();
}
function frame(now){const elapsed=Math.min((now-last)/1000,.05);last=now;if(visible&&(dirty||(playing&&!pointer))){if(playing&&!pointer)rotation+=elapsed*.035;render();dirty=false}requestAnimationFrame(frame)}
function hit(e){const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;return [...hits].reverse().filter(h=>Math.hypot(x-h.x,y-h.y)<Math.max(8,h.r||3)).sort((a,b)=>Math.hypot(x-a.x,y-a.y)-Math.hypot(x-b.x,y-b.y))[0]}
canvas.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};dragged=false;canvas.setPointerCapture(e.pointerId);$('hover').hidden=true});
canvas.addEventListener('pointermove',e=>{if(pointer){const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>4)dragged=true;rotation+=dx*.008;tilt=Math.max(.16,Math.min(1.35,tilt+dy*.005));pointer.x=e.clientX;pointer.y=e.clientY;dirty=true;return}const h=hit(e);hovered=h?.planet.index??null;$('hover').hidden=!h;if(h){const tip=$('hover');tip.textContent=h.planet.date+' · '+h.planet.count+' '+data.metric;tip.style.left=Math.min(width-180,Math.max(4,h.x+12))+'px';tip.style.top=Math.max(2,h.y-44)+'px'}});
canvas.addEventListener('pointerup',e=>{if(!dragged){const h=hit(e);if(h)inspect(h.planet.index)}pointer=null});canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('lostpointercapture',()=>pointer=null);canvas.addEventListener('pointerleave',()=>{$('hover').hidden=true});
function setZoom(v){zoom=Math.max(.55,Math.min(1.7,v));dirty=true}
canvas.addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom-e.deltaY*.001)},{passive:false});
canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','+','=','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')inspect(selected-1);else if(e.key==='ArrowRight')inspect(selected+1);else setZoom(zoom+(e.key==='-'?-.1:.1))}});
$('previous').onclick=()=>inspect(selected-1);$('next').onclick=()=>inspect(selected+1);$('daySelect').onchange=e=>inspect(Number(e.target.value));
function updatePause(){$('pause').textContent=playing?'Ⅱ Pause':'▷ Play';$('pause').setAttribute('aria-pressed',String(!playing))}updatePause();
$('pause').onclick=()=>{playing=!playing;updatePause()};$('reset').onclick=()=>{rotation=-.4;tilt=.56;zoom=1;dirty=true};$('zoomIn').onclick=()=>setZoom(zoom+.1);$('zoomOut').onclick=()=>setZoom(zoom-.1);
$('export').onclick=()=>{render();const copy=document.createElement('canvas');copy.width=1600;copy.height=1050;const c=copy.getContext('2d');c.fillStyle='#080f18';c.fillRect(0,0,1600,1050);c.fillStyle='#9ae5e7';c.font='32px Arial';c.fillText('COMMIT COSMOS',65,80);c.font='20px Arial';c.fillStyle='#839caa';c.fillText((data?.demo?'DEMO DATA · ':'')+'@'+(data?.username||'')+' · '+(data?.metric||''),65,120);c.drawImage(canvas,0,160,1600,760);c.font='19px Arial';c.fillText('One planet = one day. More activity → closer to the sun.',65,1010);copy.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='commit-cosmos.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})};
$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>250000)throw Error('Choose a data.json smaller than 250 KB.');load(JSON.parse(await f.text()));$('svgLink').hidden=true;$('dataNote').textContent+=' Use the matching cosmos.svg from your generator for the README banner.'}catch(err){$('error').textContent=err.message;$('error').hidden=false}e.target.value=''};
const guide=$('guide');$('guideButton').onclick=()=>guide.showModal();$('closeGuide').onclick=$('doneGuide').onclick=()=>guide.close();
document.addEventListener('visibilitychange',()=>{visible=!document.hidden;dirty=true});new ResizeObserver(resize).observe(canvas);
fetch('data.json').then(r=>{if(!r.ok)throw Error('Could not load data.json. Run the generator or import your generated JSON.');return r.json()}).then(load).catch(err=>{$('sourceBadge').textContent='DATA UNAVAILABLE';$('identity').textContent='Import data.json to begin';$('dataNote').textContent=err.message;$('error').textContent=err.message;$('error').hidden=false});
requestAnimationFrame(frame);
